from __future__ import annotations

import json
import typing

import pytest

import llm_router._internal.providers.qwenchat
from llm_router import Model, Provider
from llm_router._internal.capabilities.content import normalize_content
from llm_router._internal.providers.base import ProviderCredential, ProviderRequest
from llm_router._internal.providers.qwenchat import QwenChatAdapter

pytestmark = pytest.mark.verification_kind("unit")

_RECORDED_TRUST_ENV: list[bool] = []


class _FakeResponse:
    def __init__(self) -> None:
        self.status_code = 200
        self.text = json.dumps(
            {
                "id": "chatcmpl-boundary-test",
                "object": "chat.completion",
                "created": 1700000000,
                "model": "qwen-plus",
                "choices": [
                    {
                        "index": 0,
                        "message": {
                            "role": "assistant",
                            "content": "Hello from mock proxy",
                        },
                        "finish_reason": "stop",
                    }
                ],
                "usage": {
                    "prompt_tokens": 12,
                    "completion_tokens": 6,
                    "total_tokens": 18,
                },
            }
        )


class _FakeClient:
    def __init__(
        self,
        *_args: typing.Any,
        timeout: float = 600.0,
        trust_env: bool = True,
        **_kwargs: typing.Any,
    ) -> None:
        self.timeout = timeout
        self.trust_env = trust_env
        _RECORDED_TRUST_ENV.append(trust_env)

    def __enter__(self) -> _FakeClient:
        return self

    def __exit__(
        self,
        *_args: typing.Any,
    ) -> None:
        pass

    def post(
        self,
        *_args: typing.Any,
        **_kwargs: typing.Any,
    ) -> _FakeResponse:
        return _FakeResponse()


def _make_request() -> ProviderRequest:
    value = "test-credential"
    return ProviderRequest(
        request_id="test-req-boundary-trust-env",
        provider=Provider.QWENCHAT,
        model=Model.QWEN_PLUS,
        provider_model="qwen-plus",
        messages=[normalize_content("hello")],
        credential=ProviderCredential(value=value),
    )


@pytest.mark.verifies("TREQ_QWENCHAT_ADAPTER_BOUNDARY[revision==1]")
def test_qwenchat_execute_disables_trust_env(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """execute() must pass trust_env=False to httpx.Client regardless of proxy env."""
    _RECORDED_TRUST_ENV.clear()
    monkeypatch.setenv("HTTP_PROXY", "http://unreachable.proxy.invalid:8080")
    monkeypatch.setenv("HTTPS_PROXY", "http://unreachable.proxy.invalid:8080")
    monkeypatch.setenv("ALL_PROXY", "http://unreachable.proxy.invalid:8080")
    monkeypatch.setattr(
        llm_router._internal.providers.qwenchat.httpx,
        "Client",
        _FakeClient,
    )

    adapter = QwenChatAdapter(base_url="http://127.0.0.1:8000")
    request = _make_request()
    result = adapter.execute(request)

    assert result is not None
    assert _RECORDED_TRUST_ENV == [False], (
        "httpx.Client must be created with trust_env=False so that proxy "
        "environment variables (HTTP_PROXY, HTTPS_PROXY, ALL_PROXY) are "
        "never honoured by the QwenChat transport layer"
    )
